CREATE OR REPLACE FUNCTION private.catches_before_write()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'INSERT' then
    if new.id is null then
      new.id := gen_random_uuid();
    end if;
    new.is_alpha := (abs(hashtext(new.id::text || 'alpha')) % 128) = 0;
  end if;
  new := private.stamp_catch_row(new);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.launch_community_round(p_dex integer, p_gender text, p_shiny boolean, p_source text, p_test boolean DEFAULT false, p_form_id integer DEFAULT NULL::integer)
 RETURNS encounter_rounds
 LANGUAGE plpgsql
AS $function$
declare
  r public.encounter_rounds;
  settings jsonb;
  chosen_dex int;
  chosen_name text;
  chosen_variant text := 'normal';
  chosen_gender text;
  chosen_level int;
  chosen_form int;
  chosen_form_label text;
  round_id uuid := gen_random_uuid();
  t timestamptz := now();
  deadlines jsonb;
  female_look boolean;
  test_out text;
  loc text;
  sev jsonb;
  vpol text;
  guc_form text;
  forced_g text;
begin
  r := private.sync_latest_round();
  if private.round_is_active(r) then
    raise exception 'A community round is already running.';
  end if;
  if exists (select 1 from private.special_events where status = 'LIVE')
     and nullif(current_setting('play.special_event_id', true), '') is null
     and coalesce(p_source, '') is distinct from 'TEST' then
    raise exception 'A Special Event is live. Normal encounters cannot overwrite it.';
  end if;
  settings := private.game_settings();
  if p_test then
    settings := coalesce(settings, '{}'::jsonb) || jsonb_build_object(
      'rewardMode', 'test',
      'testMode', true,
      'joinSeconds', 6,
      'prepareSeconds', 6,
      'throwSeconds', 6,
      'revealSeconds', 8
    );
    test_out := nullif(btrim(current_setting('play.test_outcome', true)), '');
    if test_out in ('catch', 'escape') then
      settings := settings || jsonb_build_object('testOutcome', test_out);
    end if;
    if current_setting('play.test_rewards', true) = 'true' then
      settings := settings || jsonb_build_object('testRewards', true);
    end if;
  end if;
  if p_dex is null then
    chosen_dex := private.spawn_pick_random_dex();
    chosen_form := private.canonical_form_id(chosen_dex, chosen_dex);
  else
    chosen_dex := p_dex;
    guc_form := nullif(btrim(current_setting('play.special_form_id', true)), '');
    chosen_form := coalesce(p_form_id, nullif(guc_form, '')::int, chosen_dex);
    if upper(coalesce(p_source, '')) = 'AUTO' then
      chosen_form := chosen_dex;
    end if;
    chosen_form := private.assert_form_launchable(chosen_dex, chosen_form, p_source);
  end if;
  if chosen_dex < 1 or chosen_dex > 1025 then
    raise exception 'Choose a Pokédex number from 1 to 1025.';
  end if;
  if private.spawn_band(chosen_dex) in ('LEGENDARY', 'EVENT') then
    if coalesce(p_source, '') = 'SPECIAL_EVENT'
       and nullif(current_setting('play.special_event_id', true), '') is not null then
      null;
    elsif coalesce(p_source, '') in ('ADMIN', 'ADMIN_SPECIFIC', 'TEST') and p_dex is not null then
      null;
    else
      raise exception 'Legendary and Event species can only appear through a Special Event.';
    end if;
  end if;
  if upper(coalesce(p_source, '')) = 'AUTO' and not private.form_is_base(chosen_form) then
    raise exception 'Alternate forms cannot appear in normal encounters.';
  end if;
  chosen_name := private.form_display_name(chosen_dex, chosen_form);
  select f.form_label, f.forced_gender
    into chosen_form_label, forced_g
    from public.pokemon_forms f
   where f.pokemon_form_id = chosen_form;

  if forced_g is not null then
    if p_gender is not null
       and p_gender in ('Male', 'Female', 'Genderless')
       and p_gender is distinct from forced_g then
      raise exception 'Form % requires gender % (got %).', chosen_form, forced_g, p_gender;
    end if;
    chosen_gender := forced_g;
  elsif p_gender in ('Male', 'Female', 'Genderless') then
    chosen_gender := p_gender;
  else
    chosen_gender := private.lgpe_roll_gender(chosen_dex, floor(random() * 2147483647)::int, null);
  end if;

  female_look := chosen_gender = 'Female'
    and private.form_is_base(chosen_form)
    and chosen_dex = any (private.female_visual_dex());
  vpol := upper(coalesce(nullif(current_setting('play.special_variant_policy', true), ''), ''));
  if vpol = 'FORCED_SHINY' then
    p_shiny := true;
  elsif vpol = 'DISABLED' then
    p_shiny := false;
  end if;
  if p_shiny is true then
    chosen_variant := case when female_look then 'shiny-female' else 'shiny' end;
  elsif p_shiny is false then
    chosen_variant := case when female_look then 'female' else 'normal' end;
  elsif random() < (1.0 / 4096.0) then
    chosen_variant := case when female_look then 'shiny-female' else 'shiny' end;
  else
    chosen_variant := case when female_look then 'female' else 'normal' end;
  end if;
  loc := coalesce(nullif(current_setting('play.special_location', true), ''), private.lgpe_habitat(chosen_dex));
  begin
    sev := nullif(current_setting('play.special_event_json', true), '')::jsonb;
  exception when others then
    sev := null;
  end;
  if sev is not null then
    settings := coalesce(settings, '{}'::jsonb) || jsonb_build_object('specialEvent', sev);
  end if;
  deadlines := private.round_deadlines(settings, t);
  chosen_level := private.encounter_pokemon_level(chosen_dex, round_id);
  insert into public.encounter_rounds (
    id, phase, hidden, pokemon, dex, name, variant, gender, pokemon_form_id,
    started_at, deadlines, rules, resolved, cancelled, last_action, ends_at, trigger_source, source
  ) values (
    round_id, 'join', false,
    jsonb_build_object(
      'dex', chosen_dex,
      'name', chosen_name,
      'variant', chosen_variant,
      'gender', chosen_gender,
      'location', loc,
      'level', chosen_level,
      'formId', chosen_form,
      'formKey', coalesce((select form_key from public.pokemon_forms where pokemon_form_id = chosen_form), 'base'),
      'formLabel', coalesce(chosen_form_label, 'Base'),
      'isBaseForm', private.form_is_base(chosen_form)
    ),
    chosen_dex, chosen_name, chosen_variant, chosen_gender, chosen_form,
    t, deadlines, settings, false, false,
    case when p_test then '[TEST MODE] ' else '' end || chosen_name || ' appeared!',
    (deadlines->>'join')::timestamptz,
    p_source,
    'play'
  ) returning * into r;
  return r;
end;
$function$

CREATE OR REPLACE FUNCTION private.lgpe_pick_moves(p_dex integer, p_level integer)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  picked text[];
begin
  select coalesce(array_agg(x.n order by x.ord), '{}'::text[])
    into picked
    from (
      select m->>'n' as n, row_number() over (order by coalesce((m->>'l')::int, 0) desc, m->>'n') as ord
      from public.lgpe_species s
      cross join lateral jsonb_array_elements(s.moves) m
      where s.dex = p_dex
        and coalesce(m->>'m', 'level-up') = 'level-up'
        and coalesce((m->>'l')::int, 0) <= greatest(coalesce(p_level, 1), 1)
      limit 4
    ) x;
  if coalesce(cardinality(picked), 0) = 0 then
    select coalesce(array_agg(x.n order by x.ord), '{}'::text[])
      into picked
      from (
        select m->>'n' as n, row_number() over (order by coalesce((m->>'l')::int, 0), m->>'n') as ord
        from public.lgpe_species s
        cross join lateral jsonb_array_elements(s.moves) m
        where s.dex = p_dex
        limit 4
      ) x;
  end if;
  if coalesce(cardinality(picked), 0) = 0 then
    picked := array['Tackle'];
  end if;
  return picked;
end;
$function$

CREATE OR REPLACE FUNCTION private.lgpe_roll_gender(p_dex integer, p_seed integer, p_current text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  rate int := private.lgpe_gender_rate(p_dex);
  cur text := coalesce(p_current, '');
begin
  if rate = -1 then
    return 'Genderless';
  end if;
  if rate = 0 then
    return 'Male';
  end if;
  if rate = 8 then
    return 'Female';
  end if;
  if cur in ('Male', 'Female') then
    return cur;
  end if;
  if (abs(p_seed) % 8) < rate then
    return 'Female';
  end if;
  return 'Male';
end;
$function$

CREATE OR REPLACE FUNCTION private.materialize_streamlink_catch(p_user_id uuid, p_form_id integer, p_level integer, p_ctx text, p_source_key text, p_ball text DEFAULT 'poke'::text, p_round_id uuid DEFAULT NULL::uuid, p_shiny boolean DEFAULT false, p_content_build text DEFAULT 'sl-ref-20261013-227b573'::text, p_hidden_ticket text DEFAULT NULL::text, p_variant text DEFAULT 'normal'::text, p_name text DEFAULT NULL::text, p_gender text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  v_dex int;
  v_name text;
  inserted uuid;
  v_public text;
BEGIN
  IF private.streamlink_wire_is_enabled() THEN
    RETURN private.persist_streamlink_catch(
      p_user_id, p_form_id, p_level, p_ctx, p_source_key, p_ball, p_round_id,
      p_shiny, p_content_build, p_hidden_ticket, p_variant, p_name, p_gender
    );
  END IF;

  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('missing-user'), 'path', 'stamp');
  END IF;
  IF p_ctx IS NULL OR p_ctx NOT IN ('catch', 'grant', 'event') THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('bad-ctx'), 'path', 'stamp');
  END IF;
  IF p_source_key IS NULL OR btrim(p_source_key) = '' THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('missing-source-key'), 'path', 'stamp');
  END IF;
  IF p_ctx IN ('grant', 'event') AND private.streamlink_protected_trainer(p_user_id) THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('protected-trainer'), 'path', 'stamp');
  END IF;

  SELECT f.dex, initcap(replace(s.slug, '-', ' '))
    INTO v_dex, v_name
  FROM private.ref_forms f
  JOIN private.ref_species s
    ON s.content_build = f.content_build AND s.dex = f.dex
  WHERE f.content_build = coalesce(p_content_build, 'sl-ref-20261013-227b573')
    AND f.form_id = p_form_id;
  v_dex := coalesce(v_dex, p_form_id);
  v_name := coalesce(nullif(btrim(p_name), ''), v_name, 'Pokemon');

  BEGIN
    INSERT INTO public.catches (
      user_id, dex, name, variant, gender, ball, round_id, source_key, level, pokemon_form_id
    ) VALUES (
      p_user_id,
      v_dex,
      v_name,
      coalesce(nullif(btrim(p_variant), ''), 'normal'),
      coalesce(nullif(btrim(p_gender), ''), 'M'),
      coalesce(nullif(btrim(p_ball), ''), 'poke'),
      p_round_id,
      p_source_key,
      p_level,
      p_form_id
    )
    RETURNING id, public_id INTO inserted, v_public;
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object(
      'ok', false,
      'errors', jsonb_build_array('already-settled'),
      'replay', true,
      'path', 'stamp'
    );
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'catchId', inserted,
    'publicId', v_public,
    'path', 'stamp'
  );
END
$function$

CREATE OR REPLACE FUNCTION private.persist_streamlink_catch(p_user_id uuid, p_form_id integer, p_level integer, p_ctx text, p_source_key text, p_ball text DEFAULT 'poke'::text, p_round_id uuid DEFAULT NULL::uuid, p_shiny boolean DEFAULT false, p_content_build text DEFAULT 'sl-ref-20261013-227b573'::text, p_hidden_ticket text DEFAULT NULL::text, p_variant text DEFAULT 'normal'::text, p_name text DEFAULT NULL::text, p_gender text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  catch_id uuid;
  prep jsonb;
  mon jsonb;
  legal jsonb;
  ticket_uuid uuid;
  v_name text;
  v_variant text;
  v_public text;
  legacy text[];
  inserted uuid;
BEGIN
  IF NOT private.streamlink_wire_is_enabled() THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('wire-disabled'), 'path', 'stamp');
  END IF;
  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('missing-user'));
  END IF;
  IF p_ctx IS NULL OR p_ctx NOT IN ('catch', 'grant', 'event') THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('bad-ctx'));
  END IF;
  IF p_source_key IS NULL OR btrim(p_source_key) = '' THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('missing-source-key'));
  END IF;
  IF p_ctx = 'catch' AND p_source_key NOT LIKE 'play:%' THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('bad-source-key'));
  END IF;
  IF p_ctx = 'grant' AND p_source_key NOT LIKE 'grant:%' THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('bad-source-key'));
  END IF;
  IF p_ctx = 'event' AND p_source_key NOT LIKE 'event:%' THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('bad-source-key'));
  END IF;
  IF p_ctx IN ('grant', 'event') AND private.streamlink_protected_trainer(p_user_id) THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('protected-trainer'));
  END IF;

  catch_id := gen_random_uuid();
  prep := private.streamlink_generate_prepare(
    p_form_id, p_level, p_ctx, coalesce(p_content_build, 'sl-ref-20261013-227b573'), p_hidden_ticket
  );
  IF (prep->>'ok') IS DISTINCT FROM 'true' THEN
    RETURN prep;
  END IF;

  mon := private.streamlink_complete_and_bind(
    prep,
    coalesce(p_shiny, false),
    (private.streamlink_secure_u32() % 25)::int + 1,
    (private.streamlink_secure_u32() % 2147483647)::int,
    (private.streamlink_secure_u32() % 32)::int,
    (private.streamlink_secure_u32() % 32)::int,
    (private.streamlink_secure_u32() % 32)::int,
    (private.streamlink_secure_u32() % 32)::int,
    (private.streamlink_secure_u32() % 32)::int,
    (private.streamlink_secure_u32() % 32)::int,
    private.streamlink_secure_u32(),
    catch_id
  );
  IF (mon->>'ok') IS DISTINCT FROM 'true' THEN
    RETURN mon;
  END IF;

  IF (prep->>'ticketUuid') IS NOT NULL AND btrim(prep->>'ticketUuid') <> '' THEN
    ticket_uuid := (prep->>'ticketUuid')::uuid;
  END IF;
  legal := private.assert_streamlink_legal(mon, p_ctx, ticket_uuid);
  IF (legal->>'ok') IS DISTINCT FROM 'true' THEN
    RETURN legal;
  END IF;

  SELECT initcap(replace(s.slug, '-', ' '))
    INTO v_name
  FROM private.ref_species s
  WHERE s.content_build = prep->>'build'
    AND s.dex = private.streamlink_json_int(prep->'dex');
  v_name := coalesce(nullif(btrim(p_name), ''), v_name, 'Pokemon');
  v_variant := CASE
    WHEN coalesce(p_shiny, false) THEN 'shiny'
    ELSE coalesce(nullif(btrim(p_variant), ''), 'normal')
  END;
  v_public := private.streamlink_next_public_id('SL');
  SELECT coalesce(array_agg(x), ARRAY[]::text[])
    INTO legacy
  FROM jsonb_array_elements_text(mon->'legacyMoves') x;

  BEGIN
    INSERT INTO public.catches (
      id, user_id, dex, name, variant, gender, ball, round_id, source_key,
      public_id, level, pokemon_form_id,
      iv_hp, iv_atk, iv_def, iv_spa, iv_spd, iv_spe,
      moves, friendship, height_m, weight_kg,
      nature_id, ability_id, ability_slot,
      ev_hp, ev_atk, ev_def, ev_spa, ev_spd, ev_spe,
      move_slots, ruleset_id, content_build,
      hp_current, hp_max, status, held_item, gigantamax_factor
    ) VALUES (
      catch_id,
      p_user_id,
      private.streamlink_json_int(mon->'dex'),
      v_name,
      v_variant,
      coalesce(nullif(btrim(p_gender), ''), mon->>'gender'),
      coalesce(nullif(btrim(p_ball), ''), 'poke'),
      p_round_id,
      p_source_key,
      v_public,
      private.streamlink_json_int(mon->'level'),
      private.streamlink_json_int(mon->'formId'),
      private.streamlink_json_int(mon#>'{ivs,hp}'),
      private.streamlink_json_int(mon#>'{ivs,atk}'),
      private.streamlink_json_int(mon#>'{ivs,def}'),
      private.streamlink_json_int(mon#>'{ivs,spa}'),
      private.streamlink_json_int(mon#>'{ivs,spd}'),
      private.streamlink_json_int(mon#>'{ivs,spe}'),
      legacy,
      private.streamlink_json_int(mon->'friendship'),
      (mon->>'heightM')::numeric,
      (mon->>'weightKg')::numeric,
      private.streamlink_json_int(mon->'natureId'),
      private.streamlink_json_int(mon->'abilityId'),
      mon->>'abilitySlot',
      0, 0, 0, 0, 0, 0,
      mon->'moveSlots',
      mon->>'rulesetId',
      mon->>'contentBuild',
      private.streamlink_json_int(mon->'hpCurrent'),
      private.streamlink_json_int(mon->'hpMax'),
      NULL,
      NULL,
      false
    )
    RETURNING id INTO inserted;
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object(
      'ok', false,
      'errors', jsonb_build_array('already-settled'),
      'replay', true,
      'path', 'wire'
    );
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'catchId', inserted,
    'publicId', v_public,
    'path', 'wire',
    'mon', mon
  );
END
$function$

CREATE OR REPLACE FUNCTION private.public_ledger_lockdown_self_test()
 RETURNS TABLE(name text, passed boolean, detail text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  t text;
  can_ins boolean;
  can_upd boolean;
  can_del boolean;
  can_sel_anon boolean;
begin
  foreach t in array array[
    'candy_ledger','evolution_log','mastery_ledger','loot_rolls','reward_events',
    'loot_tables','loot_table_entries','evolution_families','evolution_config','lgpe_species'
  ] loop
    execute format('select has_table_privilege(''anon'', ''public.%I'', ''insert'')', t) into can_ins;
    execute format('select has_table_privilege(''anon'', ''public.%I'', ''update'')', t) into can_upd;
    execute format('select has_table_privilege(''anon'', ''public.%I'', ''delete'')', t) into can_del;
    name := t || ' anon cannot mutate';
    passed := (not can_ins) and (not can_upd) and (not can_del);
    detail := format('ins=%s upd=%s del=%s', can_ins, can_upd, can_del);
    return next;

    execute format('select has_table_privilege(''authenticated'', ''public.%I'', ''insert'')', t) into can_ins;
    execute format('select has_table_privilege(''authenticated'', ''public.%I'', ''update'')', t) into can_upd;
    execute format('select has_table_privilege(''authenticated'', ''public.%I'', ''delete'')', t) into can_del;
    name := t || ' authenticated cannot mutate';
    passed := (not can_ins) and (not can_upd) and (not can_del);
    detail := format('ins=%s upd=%s del=%s', can_ins, can_upd, can_del);
    return next;
  end loop;

  select has_table_privilege('anon', 'public.evolution_rules', 'insert') into can_ins;
  select has_table_privilege('anon', 'public.evolution_rules', 'update') into can_upd;
  select has_table_privilege('anon', 'public.evolution_rules', 'delete') into can_del;
  select has_table_privilege('anon', 'public.evolution_rules', 'select') into can_sel_anon;
  name := 'evolution_rules anon cannot mutate or select';
  passed := (not can_ins) and (not can_upd) and (not can_del) and (not can_sel_anon);
  detail := format('sel=%s ins=%s upd=%s del=%s', can_sel_anon, can_ins, can_upd, can_del);
  return next;

  select has_table_privilege('authenticated', 'public.evolution_rules', 'select') into can_sel_anon;
  select has_table_privilege('authenticated', 'public.evolution_rules', 'insert') into can_ins;
  name := 'evolution_rules authenticated can select only';
  passed := can_sel_anon and (not can_ins);
  detail := format('sel=%s ins=%s', can_sel_anon, can_ins);
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION private.public_round_json(r encounter_rounds)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  ph text; participants int; prepared int; thrown int; bait_count int; honey_calc jsonb; activity jsonb; honey jsonb; catchers jsonb; throwers jsonb; settled boolean; species_types text[];
  shown_level int;
  se jsonb;
begin
  if r is null then return null; end if;
  ph := private.round_phase(r);
  select s.types into species_types from public.species s where s.dex = r.dex;
  select count(*)::int, count(*) filter (where prep is not null)::int, count(*) filter (where ball is not null)::int, count(*) filter (where prep = 'bait')::int
    into participants, prepared, thrown, bait_count from public.encounter_players where round_id = r.id;
  honey_calc := private.capture_honey_modifier(bait_count, participants);
  select coalesce(jsonb_agg(row_to_json(x)::jsonb), '[]'::jsonb) into activity from (
    select a.display_name as name, a.kind, a.item, a.created_at as at from public.encounter_activity a where a.round_id = r.id order by a.created_at desc, a.id desc limit 40) x;
  select coalesce(jsonb_agg(jsonb_build_object('name', coalesce(private.trainer_label(ep.user_id), 'Trainer')) order by coalesce(private.trainer_label(ep.user_id), 'Trainer')), '[]'::jsonb)
    into honey from public.encounter_players ep where ep.round_id = r.id and ep.prep = 'bait';
  select coalesce(jsonb_agg(jsonb_build_object('name', coalesce(private.trainer_label(ep.user_id), 'Trainer'), 'ball', ep.ball) order by coalesce(private.trainer_label(ep.user_id), 'Trainer')), '[]'::jsonb)
    into throwers from public.encounter_players ep where ep.round_id = r.id and ep.ball is not null;
  select exists (select 1 from public.encounter_players ep where ep.round_id = r.id and ep.result is not null) into settled;
  if settled then
    select coalesce(jsonb_agg(jsonb_build_object('name', coalesce(private.trainer_label(ep.user_id), 'Trainer'), 'ball', ep.ball) order by coalesce(private.trainer_label(ep.user_id), 'Trainer')), '[]'::jsonb)
      into catchers from public.encounter_players ep where ep.round_id = r.id and coalesce(ep.caught, false);
  else catchers := '[]'::jsonb; end if;
  shown_level := coalesce(nullif(r.pokemon->>'level', '')::int, private.encounter_pokemon_level(r.dex, r.id));
  if shown_level is not null and shown_level < 1 then shown_level := null; end if;
  se := case when coalesce(r.rules->'specialEvent'->>'id', '') = '' then null else r.rules->'specialEvent' end;
  return jsonb_build_object(
    'id', r.id, 'source', r.source, 'phase', ph, 'overlayPhase', r.phase, 'paused', private.round_paused(r), 'hidden', r.hidden, 'cancelled', r.cancelled, 'resolved', r.resolved, 'pausedAt', r.paused_at,
    'pausedForBreak', private.director_has_reason(coalesce(r.pause_reasons, '[]'::jsonb), 'AD'),
    'pauseReasons', coalesce(r.pause_reasons, '[]'::jsonb),
    'triggerSource', r.trigger_source,
    'dex', r.dex, 'name', r.name, 'variant', r.variant, 'gender', r.gender, 'level', shown_level, 'types', coalesce(to_jsonb(species_types), '[]'::jsonb),
    'location', coalesce(nullif(r.pokemon->>'location', ''), private.lgpe_habitat(r.dex)), 'startedAt', r.started_at, 'endsAt', private.phase_display_ends(r, ph), 'deadlines', r.deadlines,
    'updatedAt', r.updated_at, 'serverNow', now(),
    'participants', participants, 'prepared', prepared, 'thrown', thrown, 'honeyContributors', bait_count, 'honeyParticipants', participants,
    'honeyMultiplier', (honey_calc->>'multiplier')::numeric, 'baitBonusPercent', round(100 * ((honey_calc->>'multiplier')::numeric - 1), 1),
    'lastAction', r.last_action, 'activity', activity, 'honeyTrainers', coalesce(honey, '[]'::jsonb), 'throwers', coalesce(throwers, '[]'::jsonb), 'catchers', coalesce(catchers, '[]'::jsonb),
    'specialEvent', se,
    'results', case when settled then (select jsonb_build_object('caught', count(*) filter (where coalesce(caught, false))::int, 'escaped', count(*) filter (where result = 'Escaped')::int, 'noThrow', count(*) filter (where coalesce(result, '') = 'No throw')::int, 'catchers', coalesce(catchers, '[]'::jsonb)) from public.encounter_players where round_id = r.id) else null end
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.special_event_preset(p_dex integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  nm text;
  legendary boolean;
  mythical boolean;
begin
  select s.name, s.is_legendary, coalesce(s.mythical, false)
    into nm, legendary, mythical
    from public.species s where s.dex = p_dex;
  if nm is null then
    raise exception 'Unknown species.';
  end if;
  if p_dex = 144 then
    return jsonb_build_object(
      'eventType', 'LEGENDARY', 'variantPolicy', 'NORMAL_ROLL', 'visibility', 'PUBLIC',
      'title', 'THE FROZEN LEGEND AWAKENS', 'subtitle', nm,
      'announcement', 'A Legendary encounter is scheduled. Join during the stream to participate.',
      'locationKey', 'seafoam-islands', 'locationLabel', 'Seafoam Islands',
      'encounterCount', 3, 'repeatPolicy', 'SEASONAL'
    );
  elsif p_dex = 145 then
    return jsonb_build_object(
      'eventType', 'LEGENDARY', 'variantPolicy', 'NORMAL_ROLL', 'visibility', 'PUBLIC',
      'title', 'THE STORM CALLS', 'subtitle', nm,
      'announcement', 'A Legendary encounter is scheduled. Join during the stream to participate.',
      'locationKey', 'power-plant', 'locationLabel', 'Power Plant',
      'encounterCount', 3, 'repeatPolicy', 'SEASONAL'
    );
  elsif p_dex = 146 then
    return jsonb_build_object(
      'eventType', 'LEGENDARY', 'variantPolicy', 'NORMAL_ROLL', 'visibility', 'PUBLIC',
      'title', 'THE SKY BURNS', 'subtitle', nm,
      'announcement', 'A Legendary encounter is scheduled. Join during the stream to participate.',
      'locationKey', 'victory-road', 'locationLabel', 'Victory Road',
      'encounterCount', 3, 'repeatPolicy', 'SEASONAL'
    );
  elsif p_dex = 150 then
    return jsonb_build_object(
      'eventType', 'LEGENDARY', 'variantPolicy', 'NORMAL_ROLL', 'visibility', 'PUBLIC',
      'title', 'THE CAVE STIRS', 'subtitle', nm,
      'announcement', 'A Legendary encounter is scheduled. Join during the stream to participate.',
      'locationKey', 'cerulean-cave', 'locationLabel', 'Cerulean Cave',
      'encounterCount', 3, 'repeatPolicy', 'SEASONAL'
    );
  elsif p_dex = 151 then
    return jsonb_build_object(
      'eventType', 'MYTHICAL', 'variantPolicy', 'NORMAL_ROLL', 'visibility', 'HIDDEN',
      'title', 'A MYTH RETURNS', 'subtitle', nm,
      'announcement', 'A special stream moment is being prepared.',
      'locationKey', 'faraway-place', 'locationLabel', 'Faraway place',
      'encounterCount', 1, 'repeatPolicy', 'ANNIVERSARY'
    );
  elsif mythical then
    return jsonb_build_object(
      'eventType', 'MYTHICAL', 'variantPolicy', 'NORMAL_ROLL', 'visibility', 'HIDDEN',
      'title', 'MYTHICAL ENCOUNTER', 'subtitle', nm,
      'announcement', 'A special stream moment is being prepared.',
      'locationKey', null, 'locationLabel', private.lgpe_habitat(p_dex),
      'encounterCount', 1, 'repeatPolicy', 'ADMIN'
    );
  elsif legendary then
    return jsonb_build_object(
      'eventType', 'LEGENDARY', 'variantPolicy', 'NORMAL_ROLL', 'visibility', 'PUBLIC',
      'title', 'LEGENDARY ENCOUNTER', 'subtitle', nm,
      'announcement', 'A Legendary encounter is scheduled. Join during the stream to participate.',
      'locationKey', null, 'locationLabel', private.lgpe_habitat(p_dex),
      'encounterCount', 3, 'repeatPolicy', 'SEASONAL'
    );
  else
    return jsonb_build_object(
      'eventType', 'SPECIAL', 'variantPolicy', 'NORMAL_ROLL', 'visibility', 'PUBLIC',
      'title', 'SPECIAL ENCOUNTER', 'subtitle', nm,
      'announcement', 'A special encounter is scheduled.',
      'locationKey', null, 'locationLabel', private.lgpe_habitat(p_dex),
      'encounterCount', 1, 'repeatPolicy', 'ADMIN'
    );
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.special_event_public_card(e private.special_events, p_admin boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  nm text;
  remaining int;
  mine jsonb;
  uid uuid := auth.uid();
begin
  if e.id is null then
    return null;
  end if;
  if not p_admin and e.visibility = 'HIDDEN' and e.rounds_launched < 1 then
    return null;
  end if;
  select name into nm from public.species where dex = e.dex;
  remaining := greatest(e.encounter_count - e.rounds_launched, 0);
  if uid is not null then
    select jsonb_build_object(
      'participated', count(*) > 0,
      'caught', count(*) filter (where coalesce(ep.caught, false)) > 0,
      'escaped', count(*) filter (where ep.result = 'Escaped') > 0
    ) into mine
    from private.special_event_rounds ser
    join public.encounter_players ep on ep.round_id = ser.round_id and ep.user_id = uid
    where ser.event_id = e.id;
  end if;
  return jsonb_build_object(
    'id', e.id,
    'eventType', e.event_type,
    'status', e.status,
    'title', e.title,
    'subtitle', case when not p_admin and e.visibility = 'HIDDEN' and e.rounds_launched < 1 then null else e.subtitle end,
    'announcement', e.announcement,
    'dex', e.dex,
    'name', nm,
    'locationLabel', coalesce(e.location_label, private.lgpe_habitat(e.dex)),
    'locationKey', e.location_key,
    'startsAt', e.starts_at,
    'endsAt', e.ends_at,
    'remainingRounds', remaining,
    'roundsLaunched', e.rounds_launched,
    'encounterCount', e.encounter_count,
    'visibility', e.visibility,
    'repeatPolicy', e.repeat_policy,
    'serverNow', now(),
    'mine', coalesce(mine, jsonb_build_object('participated', false, 'caught', false, 'escaped', false))
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.special_event_start_round(p_id uuid)
 RETURNS encounter_rounds
 LANGUAGE plpgsql
AS $function$
declare
  e private.special_events;
  r public.encounter_rounds;
  next_index int;
  shiny boolean;
  loc text;
  fid int;
  preferred_gender text;
begin
  if not pg_try_advisory_xact_lock(hashtextextended(p_id::text, 10)) then
    raise exception 'This Special Event is already starting.';
  end if;
  select * into e from private.special_events where id = p_id for update;
  if e.id is null then
    raise exception 'Special Event not found.';
  end if;
  if e.status in ('CANCELLED', 'COMPLETED', 'DRAFT') then
    raise exception 'This Special Event cannot start rounds in status %.', e.status;
  end if;
  if exists (select 1 from private.special_events where status = 'LIVE' and id is distinct from e.id) then
    raise exception 'Another Special Event is already live.';
  end if;
  if private.director_active_round() is not null then
    raise exception 'An encounter is already active.';
  end if;
  next_index := e.rounds_launched + 1;
  if next_index > e.encounter_count then
    raise exception 'All encounters for this event have already started.';
  end if;
  if exists (select 1 from private.special_event_rounds where event_id = e.id and round_index = next_index) then
    raise exception 'This event round already started.';
  end if;
  loc := coalesce(e.location_label, private.lgpe_habitat(e.dex));
  fid := private.canonical_form_id(e.dex, coalesce(e.pokemon_form_id, e.dex));
  preferred_gender := nullif(btrim(coalesce(e.presentation->>'gender', '')), '');
  if preferred_gender is not null and preferred_gender not in ('Male', 'Female', 'Genderless') then
    preferred_gender := null;
  end if;
  perform set_config('play.special_event_id', e.id::text, true);
  perform set_config('play.special_variant_policy', e.variant_policy, true);
  perform set_config('play.special_location', loc, true);
  perform set_config('play.special_form_id', fid::text, true);
  perform set_config('play.special_event_json', private.special_event_round_meta(e)::text, true);
  shiny := case e.variant_policy
    when 'FORCED_SHINY' then true
    when 'DISABLED' then false
    else null
  end;
  r := private.director_start_now(
    e.dex,
    preferred_gender,
    shiny,
    'SPECIAL_EVENT',
    e.event_type = 'ADMIN_TEST',
    fid
  );
  insert into private.special_event_rounds (event_id, round_id, round_index)
  values (e.id, r.id, next_index);
  update private.special_events
     set rounds_launched = next_index,
         last_round_id = r.id,
         last_round_at = now(),
         next_round_at = null,
         status = 'LIVE',
         updated_at = now()
   where id = e.id;
  perform private.director_log(
    'SPECIAL_EVENT_ROUND',
    e.event_type,
    jsonb_build_object('eventId', e.id, 'roundId', r.id, 'roundIndex', next_index, 'dex', e.dex, 'formId', fid, 'gender', preferred_gender)
  );
  return r;
end;
$function$

CREATE OR REPLACE FUNCTION private.stamp_catch_row(c catches)
 RETURNS catches
 LANGUAGE plpgsql
AS $function$
declare
  seed int;
  bounds int[];
  size_roll int;
  scale numeric;
  jitter numeric;
  trainer public.profiles%rowtype;
begin
  if c.public_id is null or btrim(c.public_id) = '' then
    c.public_id := 'LG' || lpad(nextval('public.catch_serial')::text, 8, '0');
  end if;
  seed := abs(('x' || substr(md5(c.id::text), 1, 8))::bit(32)::int);
  bounds := private.lgpe_level_bounds(c.dex);
  if c.level is null then
    if c.round_id is not null then
      c.level := private.encounter_pokemon_level(c.dex, c.round_id);
    else
      c.level := bounds[1] + (seed % (greatest(bounds[2] - bounds[1], 0) + 1));
    end if;
  end if;
  if c.iv_hp is null then c.iv_hp := (('x' || substr(md5(c.id::text || 'hp'), 1, 2))::bit(8)::int) % 32; end if;
  if c.iv_atk is null then c.iv_atk := (('x' || substr(md5(c.id::text || 'atk'), 1, 2))::bit(8)::int) % 32; end if;
  if c.iv_def is null then c.iv_def := (('x' || substr(md5(c.id::text || 'def'), 1, 2))::bit(8)::int) % 32; end if;
  if c.iv_spa is null then c.iv_spa := (('x' || substr(md5(c.id::text || 'spa'), 1, 2))::bit(8)::int) % 32; end if;
  if c.iv_spd is null then c.iv_spd := (('x' || substr(md5(c.id::text || 'spd'), 1, 2))::bit(8)::int) % 32; end if;
  if c.iv_spe is null then c.iv_spe := (('x' || substr(md5(c.id::text || 'spe'), 1, 2))::bit(8)::int) % 32; end if;
  if c.size_class is null or c.size_class not in ('XS','S','M','L','XL') then
    size_roll := seed % 256;
    c.size_class := case
      when size_roll < 12 then 'XS'
      when size_roll < 72 then 'S'
      when size_roll < 184 then 'M'
      when size_roll < 244 then 'L'
      else 'XL'
    end;
  end if;
  if c.moves is null or cardinality(c.moves) = 0 then
    c.moves := private.lgpe_pick_moves(c.dex, c.level);
  end if;
  c.gender := private.lgpe_roll_gender(c.dex, seed, c.gender);
  if c.met_level is null then
    c.met_level := c.level;
  end if;
  if c.met_location is null or btrim(c.met_location) = '' then
    c.met_location := private.lgpe_habitat(c.dex);
  end if;
  if c.friendship is null then
    c.friendship := 0;
  end if;
  scale := case c.size_class
    when 'XS' then 0.81
    when 'S' then 0.91
    when 'L' then 1.09
    when 'XL' then 1.21
    else 1.0
  end;
  jitter := 0.97 + ((seed / 23) % 7) * 0.01;
  if c.height_m is null then
    c.height_m := round((0.4 + (c.dex % 17) * 0.08) * scale * jitter, 2);
  end if;
  if c.weight_kg is null then
    c.weight_kg := round((5.0 + (c.dex % 29) * 1.7) * scale * jitter, 1);
  end if;
  if c.ot_user_id is null then
    c.ot_user_id := c.user_id;
  end if;
  if c.ot_name is null or btrim(c.ot_name) = '' or c.ot_number is null then
    select * into trainer from public.profiles where id = coalesce(c.ot_user_id, c.user_id);
    if c.ot_name is null or btrim(c.ot_name) = '' then
      c.ot_name := coalesce(nullif(btrim(trainer.display_name), ''), nullif(trainer.twitch_login, ''), 'Trainer');
    end if;
    if c.ot_number is null and trainer.id is not null then
      c.ot_number := 10000 + (abs(hashtext(trainer.id::text)) % 90000);
    end if;
  end if;
  return c;
end;
$function$

CREATE OR REPLACE FUNCTION public.play_trade_create(p_catch_id uuid, p_want_dex integer DEFAULT NULL::integer, p_note text DEFAULT NULL::text, p_accept_any boolean DEFAULT true, p_want_gender text DEFAULT NULL::text, p_want_shiny boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uid uuid := auth.uid();
  c public.catches;
  listing public.trade_listings;
  note text := left(btrim(coalesce(p_note, '')), 80);
  accept boolean := coalesce(p_accept_any, true);
  want_gender text := nullif(p_want_gender, '');
  want_shiny boolean := coalesce(p_want_shiny, false);
  rate int;
begin
  if uid is null then
    raise exception 'Sign in to list a Pokémon for trade.' using errcode = '42501';
  end if;
  select * into c from public.catches where id = p_catch_id and user_id = uid and transferred_at is null;
  if c.id is null then
    raise exception 'That Pokémon is not in your storage.';
  end if;
  if p_want_dex is not null and (p_want_dex < 1 or p_want_dex > 151) then
    raise exception 'Wanted Pokémon must be from the Kanto Pokédex.';
  end if;
  if p_want_dex is null then
    accept := true;
    want_gender := null;
    want_shiny := false;
  else
    rate := private.lgpe_gender_rate(p_want_dex);
    if rate is null or rate = -1 or rate = 0 or rate = 8 then
      want_gender := null;
    elsif want_gender is not null and want_gender not in ('Male', 'Female') then
      want_gender := null;
    end if;
  end if;
  if p_want_dex is null and accept is not true then
    raise exception 'Choose a Pokémon you want, or take other offers.';
  end if;
  perform private.pull_from_team(uid, c.id);
  insert into public.trade_listings (catch_id, user_id, want_dex, note, accept_any, want_gender, want_shiny)
  values (c.id, uid, p_want_dex, nullif(note, ''), accept, want_gender, want_shiny)
  on conflict (catch_id) do update
    set status = 'open',
        want_dex = excluded.want_dex,
        note = excluded.note,
        accept_any = excluded.accept_any,
        want_gender = excluded.want_gender,
        want_shiny = excluded.want_shiny,
        user_id = uid,
        created_at = now()
    where public.trade_listings.status <> 'open'
  returning * into listing;
  if listing.id is null then
    raise exception 'That Pokémon is already on the trade board.';
  end if;
  return jsonb_build_object('ok', true, 'message', 'Listed on the Global Trade System.', 'listing', private.trade_listing_json(listing));
end;
$function$
